input.command:
mongosh --quiet --host 127.0.0.1 --port 27017 --eval '
db.getSiblingDB("admin").createUser({
  user: "benchmark_user",
  pwd: "benchmark_pass",
  roles: [ { role: "root", db: "admin" } ]
});
print("admin user created");
' 2>&1

mongosh --quiet --host 127.0.0.1 --port 27017 \
  --username benchmark_user --password benchmark_pass --authenticationDatabase admin \
  --eval '
db.getSiblingDB("benchmark_db").createUser({
  user: "benchmark_user",
  pwd: "benchmark_pass",
  roles: [ { role: "readWrite", db: "benchmark_db" }, { role: "dbOwner", db: "benchmark_db" } ]
});
print("benchmark_db user created");
' 2>&1

